// ============================================================
// 1) functions/api/instagram.js  (Cloudflare Pages Function)
//    Pattern copied from functions/api/menu.js: edge cache + fallback-first.
//    Bindings: BEHOLD_FEED_ID (plain env var; the feed id is not a secret)
//              IG_TTL (optional, seconds; default 43200 = 12 h)
//    No BEHOLD_FEED_ID set -> serves the hand-picked fallback (option b).
// ============================================================
const DEFAULT_TTL = 43200;          // Behold free refreshes once/day; cache is per-colo
const MAX_POSTS = 6;                // Behold free cap
const IG_HOST = /^(www\.)?instagram\.com$/;
const IMG_HOST = /(^|\.)behold\.pictures$/;   // live feed uses behold.pictures; v2 docs show cdn*.behold.pictures
const RGB = /^\d{1,3},\d{1,3},\d{1,3}$/;

function safeUrl(u, hostRe, base) {
  try {
    const x = new URL(u, base);
    if (x.protocol !== 'https:' && !(base && x.origin === new URL(base).origin)) return null;
    if (hostRe && !hostRe.test(x.hostname)) return null;
    return x.toString();
  } catch { return null; }
}

function fromBehold(feed) {
  const out = [];
  for (const p of feed?.posts || []) {
    const s = p.sizes || {};
    const href = safeUrl(p.permalink, IG_HOST);
    const img = s.medium && safeUrl(s.medium.mediaUrl, IMG_HOST);
    if (!href || !img) continue;
    const srcset = ['small', 'medium', 'large']
      .filter((k) => s[k] && safeUrl(s[k].mediaUrl, IMG_HOST))
      .map((k) => `${s[k].mediaUrl} ${s[k].width}w`).join(', ');
    const caption = (p.prunedCaption || '').trim();
    out.push({
      href, img, srcset,
      w: s.medium.width || 700, h: s.medium.height || 700,
      // altText is often missing (never on Reels) -> first caption line -> generic
      alt: (p.altText || caption.split('\n')[0] || 'Instagram post from Layers Superfood Bar').slice(0, 140),
      kind: p.mediaType === 'VIDEO' ? (p.isReel ? 'reel' : 'video') : p.mediaType === 'CAROUSEL_ALBUM' ? 'album' : 'image',
      color: RGB.test(p.colorPalette?.dominant || '') ? p.colorPalette.dominant : null,
    });
    if (out.length >= MAX_POSTS) break;
  }
  return out;
}

function fromFallback(json, base) {
  return (json?.posts || []).map((p) => ({
    href: safeUrl(p.href, IG_HOST),
    img: safeUrl(p.img, null, base),            // same-origin /assets/img/ig/...
    srcset: '', w: p.w || 700, h: p.h || 700,
    alt: String(p.alt || 'Instagram post from Layers Superfood Bar').slice(0, 140),
    kind: 'image', color: null,
  })).filter((p) => p.href && p.img).slice(0, MAX_POSTS);
}

function json(body, sMaxAge) {
  return new Response(JSON.stringify(body), {
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': `public, max-age=600, s-maxage=${sMaxAge}`,
      'x-content-type-options': 'nosniff',
    },
  });
}

export async function onRequestGet(context) {
  const { request, env } = context;
  const ttl = Number(env.IG_TTL) || DEFAULT_TTL;
  const cache = caches.default;
  const key = new Request(new URL('/api/instagram', request.url).toString());
  const hit = await cache.match(key);
  if (hit) return hit;

  try {
    if (!env.BEHOLD_FEED_ID) throw new Error('no feed configured');
    const res = await fetch(`https://feeds.behold.so/${encodeURIComponent(env.BEHOLD_FEED_ID)}`, {
      headers: { accept: 'application/json' },
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) throw new Error(`behold ${res.status}`);   // incl. paused account
    const posts = fromBehold(await res.json());
    if (posts.length < 3) throw new Error('feed too short');
    const out = json({ source: 'behold', syncedAt: new Date().toISOString(), posts }, ttl);
    context.waitUntil(cache.put(key, out.clone()));
    return out;
  } catch {
    let fb = null;
    try {
      const r = await fetch(new URL('/assets/data/instagram-fallback.json', request.url));
      if (r.ok) fb = await r.json();
    } catch {}
    // Cache the fallback briefly so a Behold outage/pause doesn't burn quota.
    const out = json({ source: 'fallback', posts: fromFallback(fb, request.url) }, 900);
    context.waitUntil(cache.put(key, out.clone()));
    return out;
  }
}

<!-- ============================================================
     2) Markup (src-pages). build-pages.py pre-renders the <li>s from
        instagram-fallback.json, so no-JS and API failures still show posts.
     ============================================================ -->
<section class="ig" aria-labelledby="ig-title">
  <h2 id="ig-title">Fresh from our Instagram</h2>
  <!-- role="list": Safari/VoiceOver drops list semantics when list-style:none -->
  <ul class="ig-grid" role="list" data-ig-grid>
    <li class="ig-card">
      <a class="ig-link" href="https://www.instagram.com/p/SHORTCODE/">
        <img src="/assets/img/ig/acai-bowl.webp" width="700" height="700"
             alt="Açaí bowl topped with strawberries, banana and granola"
             loading="lazy" decoding="async">
        <span class="sr-only"> (on Instagram)</span>
      </a>
    </li>
    <!-- ...up to 6 -->
  </ul>
  <p><a class="ig-follow" href="https://www.instagram.com/layerssuperfoodbar/">Follow @layerssuperfoodbar</a></p>
</section>
<script src="/assets/js/instagram-grid.js" defer></script>

// ============================================================
// 3) public/assets/js/instagram-grid.js — progressive enhancement
// ============================================================
(() => {
  const list = document.querySelector('[data-ig-grid]');
  if (!list || !window.fetch) return;
  const IG = /^(www\.)?instagram\.com$/;
  const IMG = /(^|\.)behold\.pictures$/;
  const ok = (u, re) => {
    try {
      const x = new URL(u, location.href);
      return x.origin === location.origin || (x.protocol === 'https:' && re.test(x.hostname)) ? x.href : null;
    } catch { return null; }
  };
  const LABEL = { video: 'Video', reel: 'Reel', album: 'Album' };

  function card(p) {
    const li = document.createElement('li');
    li.className = 'ig-card';
    if (p.color) li.style.setProperty('--ig-ph', `rgb(${p.color})`);   // pre-validated "R,G,B"
    const a = document.createElement('a');
    a.className = 'ig-link';
    a.href = p.href;
    const img = new Image(p.w, p.h);                 // width/height -> no layout shift
    img.alt = p.alt;                                 // textContent/attrs only, never innerHTML
    img.loading = 'lazy';
    img.decoding = 'async';
    if (p.srcset) { img.srcset = p.srcset; img.sizes = '(min-width: 900px) 30vw, 45vw'; }
    img.src = p.img;
    img.addEventListener('error', () => li.remove(), { once: true });
    a.append(img);
    if (LABEL[p.kind]) {
      const b = document.createElement('span');
      b.className = 'ig-badge';
      b.textContent = LABEL[p.kind];
      a.append(b);
    }
    const sr = document.createElement('span');
    sr.className = 'sr-only';
    sr.textContent = ' (on Instagram)';
    a.append(sr);
    li.append(a);
    return li;
  }

  async function load() {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 6000);
    try {
      const res = await fetch('/api/instagram', { signal: ctrl.signal, headers: { accept: 'application/json' } });
      if (!res.ok) return;                               // keep pre-rendered fallback
      const { posts } = await res.json();
      if (!Array.isArray(posts)) return;
      const frag = document.createDocumentFragment();
      for (const p of posts) {
        const href = ok(p.href, IG), img = ok(p.img, IMG);
        if (href && img && href.includes('instagram.com')) frag.append(card({ ...p, href, img }));
      }
      if (frag.childNodes.length >= 3) list.replaceChildren(frag);
    } catch { /* offline/timeout: keep fallback */ }
    finally { clearTimeout(t); }
  }

  // Only fetch when the section is near the viewport (saves requests + bytes).
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver((es) => {
      if (es.some((e) => e.isIntersecting)) { io.disconnect(); load(); }
    }, { rootMargin: '600px 0px' });
    io.observe(list);
  } else load();
})();

/* ============================================================
   4) CSS — uses the site's own tokens; square tiles, dominant-color placeholder
   ============================================================ */
.ig-grid { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--space-2, 8px);
           grid-template-columns: repeat(2, 1fr); }
@media (min-width: 720px) { .ig-grid { grid-template-columns: repeat(3, 1fr); } }
.ig-card { position: relative; aspect-ratio: 1; overflow: hidden; border-radius: var(--radius, 12px);
           background: var(--ig-ph, var(--surface-2, #eee)); }
.ig-link { display: block; height: 100%; }
.ig-link img { width: 100%; height: 100%; object-fit: cover; display: block; }
.ig-link:focus-visible { outline: 3px solid var(--accent, currentColor); outline-offset: 3px; }
.ig-badge { position: absolute; top: 8px; right: 8px; padding: 2px 8px; border-radius: 999px;
            font-size: .75rem; background: rgb(0 0 0 / .6); color: #fff; }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .ig-link img { transition: transform .4s ease; }
  .ig-link:hover img { transform: scale(1.04); }
}

