# ============================================================
# 6) .pages.yml (repo root) — Pages CMS form so the social media manager
#    uploads a photo + pastes a post link; saves commit to GitHub -> Pages build.
#    (object/list field nesting is per the Fields docs; no nested example was found — test once.)
# ============================================================
media:
  input: public/assets/img/ig
  output: /assets/img/ig
content:
  - name: instagram
    label: Instagram picks (homepage)
    type: file
    path: public/assets/data/instagram-fallback.json
    format: json
    fields:
      - name: posts
        label: Posts (pick 6)
        type: object
        list: true
        fields:
          - { name: img,  label: Photo (square looks best), type: image }
          - { name: href, label: Instagram post link (https://www.instagram.com/p/...), type: string }
          - { name: alt,  label: Describe the photo for screen readers, type: string }

# ============================================================
# 7) Reference only — self-hosted Meta API (what you'd have to automate forever)
# ============================================================
# exchange (server-side only):
curl "https://graph.instagram.com/access_token?grant_type=ig_exchange_token&client_secret=$APP_SECRET&access_token=$SHORT_TOKEN"
# refresh (token must be >=24h old and NOT expired; good for 60 more days):
curl "https://graph.instagram.com/refresh_access_token?grant_type=ig_refresh_token&access_token=$LONG_TOKEN"
# media:
curl "https://graph.instagram.com/me/media?fields=id,caption,media_type,media_url,thumbnail_url,permalink,timestamp,alt_text&access_token=$LONG_TOKEN"
# tokenless oEmbed (since 2026-06-15) — returns Instagram's own blockquote+iframe HTML, not stylable:
curl "https://graph.facebook.com/v26.0/instagram_oembed?url=https://www.instagram.com/p/SHORTCODE/&omitscript=true&maxwidth=540"
